  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  ADMIN\n  UMPIRE\n  ORGANIZER\n  VIEWER\n}\n\nenum MatchStatus {\n  PENDING // Waiting for players\n  READY // Players ready, waiting for schedule\n  SCHEDULED // Time assigned\n  ONGOING // Live\n  COMPLETED // Done\n  CANCELLED\n}\n\nmodel User {\n  id           String @id @default(cuid())\n  email        String @unique\n  passwordHash String\n  name         String\n  role         Role   @default(VIEWER)\n\n  // Relations\n  umpiredMatches     Match[]            @relation(\"Umpire\")\n  assignedMatchCodes MatchCode[]        @relation(\"AssignedUmpire\")\n  resultAudits       MatchResultAudit[]\n  codeUsages         MatchCodeUsage[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Player {\n  id            String         @id @default(uuid())\n  playerId      String         @unique @default(cuid()) // Unique player ID (e.g., XS-ABC123)\n  name          String\n  email         String?        @unique\n  gender        String?\n  weight        String?\n  category      String?\n  description   String?\n  clubId        String?\n  club          Club?          @relation(fields: [clubId], references: [id])\n  registrations Registration[]\n  lockers       Locker[] // Locker assignments\n  stats         PlayerStats? // Overall statistics\n\n  // Enhanced Fixture Engine fields\n  elo    Int? // ELO rating for advanced seeding\n  region String? // Geographic region for distribution optimization\n\n  matchesAsA Match[] @relation(\"PlayerA\")\n  matchesAsB Match[] @relation(\"PlayerB\")\n  winnerOf   Match[] @relation(\"Winner\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Club {\n  id          String   @id @default(uuid())\n  name        String   @unique\n  location    String?\n  description String?\n  players     Player[]\n}\n\nmodel Tournament {\n  id        String   @id @default(uuid())\n  name      String\n  location  String?\n  startDate DateTime\n  endDate   DateTime\n  events    Event[]\n  courts    Court[]\n  lockers   Locker[] // Locker assignments for this tournament\n}\n\nmodel Event {\n  id            String         @id @default(uuid())\n  name          String\n  tournamentId  String\n  sport         String         @default(\"Badminton\")\n  type          String         @default(\"KNOCKOUT\") // KNOCKOUT or ROUND_ROBIN\n  gender        String? // Men's, Women's, Mixed\n  category      String? // U15, U18, Senior, etc.\n  tournament    Tournament     @relation(fields: [tournamentId], references: [id], onDelete: Cascade)\n  matches       Match[]\n  rounds        Int?\n  registrations Registration[]\n  createdAt     DateTime       @default(now())\n}\n\nmodel Registration {\n  id       String @id @default(uuid())\n  eventId  String\n  event    Event  @relation(fields: [eventId], references: [id])\n  playerId String\n  player   Player @relation(fields: [playerId], references: [id])\n  seed     Int?\n\n  @@unique([eventId, playerId])\n}\n\nmodel Court {\n  id           String          @id @default(uuid())\n  name         String\n  tournamentId String\n  tournament   Tournament      @relation(fields: [tournamentId], references: [id])\n  schedule     ScheduleBlock[]\n}\n\nmodel Match {\n  id      String @id @default(uuid())\n  eventId String\n  event   Event  @relation(fields: [eventId], references: [id], onDelete: Cascade)\n\n  round       Int\n  matchNumber Int // 1-indexed within the round\n\n  playerAId String?\n  playerA   Player? @relation(\"PlayerA\", fields: [playerAId], references: [id])\n\n  playerBId String?\n  playerB   Player? @relation(\"PlayerB\", fields: [playerBId], references: [id])\n\n  winnerId String?\n  winner   Player? @relation(\"Winner\", fields: [winnerId], references: [id])\n\n  // Umpire Assignment (Critical for Security)\n  umpireId String?\n  umpire   User?   @relation(\"Umpire\", fields: [umpireId], references: [id])\n\n  // Scoring & Metadata\n  score    Json? // e.g. { sets: [{a: 21, b: 19}, {a: 15, b: 21}, {a: 21, b: 10}] }\n  metadata Json? // { bestOf: 3, category: \"U15\" }\n  status   MatchStatus @default(PENDING)\n\n  // Enhanced Fixture Engine fields\n  isLosersBracket Boolean @default(false) // For double elimination\n  bracketPosition Int? // For advanced bracket tracking\n\n  // Propagation Logic\n  nextMatchId     String?\n  nextMatch       Match?  @relation(\"NextMatch\", fields: [nextMatchId], references: [id])\n  previousMatches Match[] @relation(\"NextMatch\")\n\n  matchCode MatchCode?\n  schedule  ScheduleBlock?\n\n  // Audit Relations\n  resultAudits MatchResultAudit[]\n  codeUsages   MatchCodeUsage[]\n\n  startTime DateTime? // Denormalized for quick access\n  endTime   DateTime?\n\n  updatedAt DateTime @updatedAt\n}\n\nmodel MatchCode {\n  id               String   @id @default(cuid())\n  matchId          String   @unique\n  match            Match    @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  assignedUmpireId String\n  assignedUmpire   User     @relation(\"AssignedUmpire\", fields: [assignedUmpireId], references: [id])\n  codeHash         String\n  isActive         Boolean  @default(true)\n  expiresAt        DateTime\n  createdAt        DateTime @default(now())\n}\n\nmodel ScheduleBlock {\n  id        String   @id @default(uuid())\n  matchId   String   @unique\n  match     Match    @relation(fields: [matchId], references: [id])\n  courtId   String\n  court     Court    @relation(fields: [courtId], references: [id])\n  startTime DateTime\n  endTime   DateTime\n}\n\nmodel Locker {\n  id           String     @id @default(uuid())\n  lockerNumber String\n  playerId     String\n  player       Player     @relation(fields: [playerId], references: [id], onDelete: Cascade)\n  tournamentId String\n  tournament   Tournament @relation(fields: [tournamentId], references: [id], onDelete: Cascade)\n  sport        String // Only for Basketball, Cricket, Football\n  assignedAt   DateTime   @default(now())\n\n  @@unique([lockerNumber, tournamentId])\n}\n\nmodel PlayerStats {\n  id           String   @id @default(uuid())\n  playerId     String   @unique\n  player       Player   @relation(fields: [playerId], references: [id], onDelete: Cascade)\n  totalMatches Int      @default(0)\n  totalWins    Int      @default(0)\n  totalLosses  Int      @default(0)\n  totalPoints  Int      @default(0)\n  winRate      Float    @default(0)\n  updatedAt    DateTime @updatedAt\n}\n\nmodel AdminLog {\n  id        String   @id @default(uuid())\n  action    String\n  details   String\n  createdAt DateTime @default(now())\n}\n\nmodel MatchResultAudit {\n  id        String   @id @default(cuid())\n  match     Match    @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  matchId   String\n  actor     User?    @relation(fields: [actorId], references: [id])\n  actorId   String?\n  action    String // e.g. 'SUBMIT_RESULT', 'EDIT_RESULT'\n  payload   Json?\n  createdAt DateTime @default(now())\n}\n\nmodel MatchCodeUsage {\n  id        String   @id @default(cuid())\n  match     Match    @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  matchId   String\n  umpire    User?    @relation(fields: [umpireId], references: [id])\n  umpireId  String?\n  ip        String?\n  success   Boolean\n  createdAt DateTime @default(now())\n}\n\nmodel FixtureSnapshot {\n  id            String   @id @default(cuid())\n  eventId       String\n  snapshotData  Json // Stores complete fixture state for rollback\n  fairnessScore Float?\n  metadata      Json? // Additional info like format, options used\n  createdBy     String? // User who created this snapshot\n  createdAt     DateTime @default(now())\n\n  @@index([eventId])\n  @@index([createdAt])\n}\n",
